fn insert(oline: &Vec<char>, l: usize, nl: &Vec<char>, p: usize, at_pos: usize) -> Vec<char> {
    // Preconditions based on problem statement:
    // - l <= oline.len()
    // - p <= nl.len()
    // - at_pos <= l
    
    // Take first l chars from oline
    let first_part: Vec<char> = oline.iter().take(l).cloned().collect();
    // Take first p chars from nl
    let insert_part: Vec<char> = nl.iter().take(p).cloned().collect();
    
    // Build result by concatenating three parts
    let mut result = Vec::with_capacity(l + p);
    
    // 1) First A characters from first_part
    result.extend(first_part.iter().take(at_pos));
    
    // 2) All P characters from insert_part
    result.extend(insert_part.iter());
    
    // 3) Remaining (L - A) characters from first_part
    result.extend(first_part.iter().skip(at_pos));
    
    result
}